-- Model: sat_erc_transaction_curr
-- Description: Current active record for SAT_ERC_TRANSACTION using ROW_NUMBER()
-- Generated by: bv pipeline generate transform with custom template
-- Satellite Type: SAT_ON_HUB
-- Parent: hub HUB_TRANSACTION

WITH RANKED_RECORDS AS (
SELECT
    TRANSACTION_HKEY,  -- hash key
    LOAD_DATE AS _CURRENT_ACTIVE_TIMESTAMP, -- used: LOAD_DATE
    -- Satellite Attributes
    OBJECTTRANSACTIONID  ,  -- is_business_key
    LOAD_DATE            ,  -- is_load_timestamp
    LOAD_CYCLE_ID        ,  -- is_load_cycle_id
    DELETE_FLAG          ,  -- is_delete_flag
    ABOUTTYPEID          ,  -- is_other_attr
    COMMISSIONBASEAMOUNT ,  -- is_other_attr
    CREATEDBY            ,  -- is_other_attr
    CREATEDON            ,  -- is_other_attr
    DESCRIPTION          ,  -- is_other_attr
    EFFECTIVEBILLINGDATE ,  -- is_other_attr
    EFFECTIVEDATE        ,  -- is_other_attr
    GROSSPROFITAMOUNT    ,  -- is_other_attr
    INVOICEAMOUNT        ,  -- is_other_attr
    INVOICEDISCOUNTAMOUNT,  -- is_other_attr
    INVOICETAXAMOUNT     ,  -- is_other_attr
    INVOICEVMSAMOUNT     ,  -- is_other_attr
    ISINVOICEABLE        ,  -- is_other_attr
    REFERENCEDABOUTTYPEID,  -- is_other_attr
    REFERENCEDDOCSOK     ,  -- is_other_attr
    REFERENCEDNOTE       ,  -- is_other_attr
    REFERENCEDREFERENCEID,  -- is_other_attr
    TRANSACTIONAMOUNT    ,  -- is_other_attr
    TYPEID               ,  -- is_other_attr
    _FIVETRAN_ACTIVE     ,  -- is_other_attr
    _FIVETRAN_END        ,  -- is_other_attr
    _FIVETRAN_START      ,  -- is_other_attr
    _FIVETRAN_TRANS         -- is_other_attr
    ,
    ROW_NUMBER() OVER (
        PARTITION BY TRANSACTION_HKEY
        ORDER BY LOAD_DATE DESC
    ) AS row_num
FROM {{ source('eli_dv_rv', 'sat_erc_transaction') }}
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RECORDS
WHERE row_num = 1
AND DELETE_FLAG = 'N'
